body.query:
  query Document($key: String!) {
    resource(id: $key) {
      ...ResourceRedirectDetails
      ... on Document {
        ...DocumentPage
      }
    }
  }

fragment ResourceRedirectDetails on Resource {
  __typename
  ... on Article {
    id
    title
    urlAlias
  }
  ... on Composition {
    id
    maybeTitle: title
    urlAlias
  }
  ... on DataUse {
    id
    title
  }
  ... on Document {
    id
    title
  }
  ... on MeetingEvent {
    id
    title
  }
  ... on News {
    id
    title
  }
  ... on Programme {
    id
    title
  }
  ... on GbifProject {
    id
    title
  }
  ... on Tool {
    id
    title
  }
}

fragment DocumentPage on Document {
  id
  title
  createdAt
  excerpt
  summary
  primaryLink {
    label
    url
  }
  document {
    title
    description
    file {
      fileName
      url
    }
  }
  body
  citation
}
